   165→func TestLoad_XDGConfigHome(t *testing.T) {
   166→	xdg := t.TempDir()
   167→	confDir := filepath.Join(xdg, "wire")
   168→	if err := os.MkdirAll(confDir, 0o755); err != nil {
   169→		t.Fatal(err)
