   176→		t.Fatal(err)
   177→	}
   178→
   179→	t.Setenv("XDG_CONFIG_HOME", xdg)
   180→	t.Setenv("WIRE_CONFIG", "") // clear override
   181→
   182→	cfg, err := Load()
   183→	if err != nil {
   184→		t.Fatalf("unexpected error: %v", err)
   185→	}
   186→	if cfg.Listen != ":8080" {
   187→		t.Errorf("listen: got %q", cfg.Listen)
   188→	}
   189→}
