   191→func contains(s, sub string) bool {
   192→	return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
   193→		func() bool {
   194→			for i := range len(s) - len(sub) + 1 {
   195→				if s[i:i+len(sub)] == sub {
   196→					return true
   197→				}
   198→			}
   199→			return false
   200→		}())
   201→}
